        + [F("___ na dito sa Japan. (It is winter)", "Taglamig", ["Tag-init", "Taglagas"], "taglamig."), F("Ilang buwan na lang at ___ na rin. (spring)", "tagsibol", ["taglamig", "taglagas"], "tagsibol."), F("Miss ko rin ang ___ sa Pilipinas. (summer)", "tag-init", ["taglamig", "tagsibol"], "tag-init."), F("Manghang-mangha ako sa makukulay na mga ___. (trees)", "puno", ["ulap", "baha"], "puno."), F("Tuwang-tuwa ako nung ___. (it snowed)", "nagniyebe", ["nalusaw", "nagdudulot"], "nagniyebe.")]
