# ------------------------------------------------------------------ 3 grammar
_MAP = [("malakas", "may lakas", "having strength"), ("mabait", "may bait", "having goodness"), ("mabulaklak", "may bulaklak", "having many flowers"), ("mabato", "may bato", "having many stones")]
_PR = [("Maganda ang tanawin sa bundok.", "maganda – ganda", "The view on the mountain is beautiful."), ("Hindi masama ang magtapon ng asin.", "masama – sama", "It is not bad to throw salt."), ("Alam namin na marunong ang mga estudyante.", "marunong – dunong", "We know that the students are knowledgeable."), ("Mabilis ang takbo ng bus.", "mabilis – bilis", "The bus runs fast."), ("Hindi ko kaya ang mabigat na sako ng bigas.", "mabigat – bigat", "I cannot carry the heavy sack of rice.")]
