        card("Practice: identify the adjectives and their root words (the book’s key)", "", tables=[table(["Sentence", "Adjective and root", "Meaning"], [list(r) for r in _PR], say=[0])]),
        card("Ma adjectives used with weather conditions", "Ma adjectives are also used with acts of nature related to weather conditions. Study these sentences from the presentations:", examples=passage(_WS)),
        card("Meanings", "Except for masarap, mabulaklak and makukulay, most of the ma adjectives in these sentences are related to weather. Makulimlim means “cloudy, dark or overcast.” Maulan means “rainy.” Maaraw means “sunny.” Maulap means “cloudy,” and maaliwalas means “clear.”"),
        card("Activity 1: complete with ma adjectives (the book’s key)", "Word box: maulap, mahina, maalon, maaraw, malakas, maaliwalas. The completed sentences with the book’s translations (Activity 2):", examples=passage([(t, e) for t, _, e in _A1])),
        card("Activity 3: conjugate the verbs from the reading (the book’s key)", "The root word is given in parentheses in the book.", tables=[table(["Sentence", "Verb", "Root", "Meaning"], [list(r) for r in _A3], say=[0, 1, 2])]),
