_T4 = [("Makakaranas ang Kamaynilaan ng dagliang pag-ulan, pagkidlat, at pagkulog.", "Greater Manila will experience sudden rain, lightning and thunder."), ("Ibinaba na ng PAGASA sa Signal Number Isa ang babala ng bagyo sa Kalakhang Maynila.", "PAGASA has lowered the storm warning in Metro Manila to Signal Number One."), ("Maaraw at maaliwalas ang panahon ngayon sa hilagang Luzon.", "The weather today in northern Luzon is sunny and clear."), ("Pulu-pulong pag-ulan na tatagal nang isa hanggang dalawang oras ang iiral sa Cebu.", "Isolated rain showers lasting one to two hours will prevail in Cebu."), ("Maulan, maulap na may kasamang pagkulog at pagkidlat sa Silangang Bisaya.", "Rainy, cloudy with thunder and lightning in Eastern Visayas.")]
