        + [F("Maaraw at ___ ang panahon ngayon sa hilagang Luzon. (clear)", "maaliwalas", ["maalon", "mahina"], "maaliwalas."), F("Pulu-pulong ___ ang iiral sa Cebu. (rain)", "pag-ulan", ["pagbaha", "hangin"], "pag-ulan."), F("Narito ang ___ ng panahon. (forecast)", "pagtaya", ["pagkulog", "pagkidlat"], "pagtaya."), F("Kanselado ang mga domestic ___. (flights)", "flights", ["bagyo", "baha"], "flights.")]
