_WT = [("Maaraw na Panahon.", "Sunny weather."), ("Kapag maaraw ang panahon, mataas ang sikat ng araw at may kainitan.", "When the weather is sunny, the sun is high and there is some heat."), ("Maulap na Panahon.", "Cloudy weather."), ("Kung maulap naman ang panahon, mapapansin na puno ng ulap ang kalangitan.", "If the weather is cloudy, you will notice the sky is full of clouds."), ("At, bahagyang natatakpan nito ang araw.", "And they partly cover the sun."), ("Mahanging Panahon.", "Windy weather."), ("Kapag naman mahangin ang panahon, mapapansin na may kalakasan ang ihip ng hangin.", "When the weather is windy, you will notice the wind blows moderately strong."), ("Maulang panahon.", "Rainy weather."), ("Makulimlim ang langit at may pumapatak na mga tubig mula doon.", "The sky is overcast and water is falling from it.")]
