_F1 = [("Maganda nga ang panahon sa buong bansa.", "The weather is indeed nice throughout the country."), ("Kaugnay nito ang patuloy na pag-iral ng hanging amihan sa Luzon at Eastern Visayas.", "Related to this is the continued prevailing of the northeast monsoon in Luzon and Eastern Visayas."), ("Kaya sa lagay ng panahon ngayong araw, ang Cagayan Valley at mga probinsiya ng Aurora at Quezon ay makakaranas ng maulap na kalangitan na may mahihinang pag-ulan.", "So in today’s weather, Cagayan Valley and the provinces of Aurora and Quezon will experience cloudy skies with light rains."), ("Ang natitirang bahagi ng Luzon at Eastern Visayas ay makakaranas naman ng bahagyang maulap na kalangitan kaya maganda at mainit ang panahon diyan ngayon sa labas.", "The rest of Luzon and Eastern Visayas will experience partly cloudy skies, so the weather out there now is nice and hot."), ("Ganito rin ang lagay ng panahon sa natitirang bahagi ng Visayas at buong Mindanao.", "The weather is the same in the rest of Visayas and all of Mindanao.")]
_F2 = [("Bagama’t patuloy ang pag-iral ng amihan hindi na ito kalamigan at maaasahan na malapit na ang ating transition to summer.", "Although the amihan continues to prevail, it is not as cold anymore and we can expect that our transition to summer is near."), ("Kaya’t kahit hindi na ganun kalamigan ang dala ng amihan inaasahan pa rin ang maalon hanggang napakaalon na kondisyon ng karagatan kaya ibayong pag-iingat po ang ating paalala sa mga maglalayag ngayong Lunes.", "So even though the amihan is no longer that cold, rough to very rough sea conditions are still expected, so our reminder is extra caution to those who will sail this Monday.")]
