_CA = [("Adriana", "Cathy, may magandang balita ako. Napili akong mag-advanced na kurso sa Tagalog sa Lipa, Batangas. Magsisimula ang klase sa Hunyo. Ano ang panahon sa Hunyo?", "Cathy, I have good news. I was selected to take an advanced course in Tagalog in Lipa, Batangas. The class starts in June. What is the weather like in June?"), ("Cathy", "Binabati kita! Maulan ang Hunyo. Karaniwang may bagyo mula Hunyo hanggang Nobyembre.", "Congratulations! June is rainy. Typhoons normally occur from June to November."), ("Adriana", "May magaganda bang beach sa Batangas?", "Are there nice beaches in Batangas?"), ("Cathy", "Oo, maraming magagandang beach doon.", "Yes, there are many nice beaches there."), ("Adriana", "Swerte ako dahil mahilig akong lumangoy. Gusto ko pang malaman ang tungkol sa lugar pero huli na ako sa susunod kong klase.", "I am lucky because I love to swim. I want to know more about the place but I am late for my next class."), ("Cathy", "Walang problema. Puwede mo akong tawagan anumang oras.", "No problem. You can call me anytime.")]
